<script>
(()=>{const $=id=>document.getElementById(id),n=id=>parseFloat($(id).value);function go(){const vals=['nights','lodgingLimit','actualLodging','fullDays','partialDays','mealLimit','partialFactor','actualMeals'].map(n);if(vals.some(x=>!Number.isFinite(x)||x<0)||vals[6]>100){$('note').textContent='Enter non-negative values; the partial-day factor must be 0–100%.';$('note').className='helper danger';return;}const [ni,ll,al,fd,pd,ml,pf,am]=vals,s=$('currency').value||'',la=ni*ll,ma=fd*ml+pd*ml*pf/100,total=la+ma,actual=al+am,ex=Math.max(0,actual-total);$('lodgingAllow').textContent=s+la.toFixed(2);$('mealAllow').textContent=s+ma.toFixed(2);$('totalAllow').textContent=s+total.toFixed(2);$('excess').textContent=s+ex.toFixed(2);$('note').textContent='This is a comparison tool. Enter the official rate, partial-day rule, tax treatment and eligible expense basis from the policy that actually governs the trip.';$('note').className='helper'+(ex>0?' danger':'');}
['nights','lodgingLimit','actualLodging','fullDays','partialDays','mealLimit','partialFactor','actualMeals','currency'].forEach(id=>$(id).addEventListener('input',go));$('calc').onclick=go;$('reset').onclick=()=>{$('nights').value=3;$('lodgingLimit').value=180;$('actualLodging').value=570;$('fullDays').value=2;$('partialDays').value=2;$('mealLimit').value=80;$('partialFactor').value=75;$('actualMeals').value=250;$('currency').value='$';go();};go();})();
</script>
